/**
 * Night Inspection
 * ----------------
 * Nehemiah rises by night with a few men and inspects the broken walls and gates, telling no one. Stage: a ruined city at midnight, a torch in the rubble, a man on foot by the wall; a broken gate, a pool, a valley of darkness; the plan being made in silence.
 *
 * Palette 0x2a1a10 → 0x060402 · light: ember · hero: gate
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./nehemiah-kit.js.
 */

import { THREE, createScene, cityGate, house, person } from './nehemiah-kit.js';

const BG = 0x2a1a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 3250508915, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [21, 0, -58], { name: 'city', r: [0, -0.08, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* hero: the gate */
    cityGate(W, group, 0, 0, -6, 1.0, { stone: 0x060402, trim: 0x050302 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x301e12, wrapTrim: 0x1d120b, beard: 'long', staff: 'planted', ry: -0.57, s: 1.13 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x301e12, wrapTrim: 0x1d120b, beard: 'long', staff: 'planted', ry: 0.36, s: 1.12 });

    return W.finish();
}

export default { build };
